<template><section class="sync-panel"><header><div><h3>Snackbar sync</h3><p>One coordinator for app connections and local exchange.</p></div><button class="usx-btn" @click="router.push('/system?tab=apps')"><UIcon name="apps" />Manage apps</button><button class="usx-btn" :disabled="busy" @click="load"><UIcon name="refresh" />Refresh</button></header><p v-if="error" role="alert">{{ error }}</p><p v-if="!connections.length">No app connections configured. Local tasks and notes remain available.</p><article v-for="item in connections" :key="item.id"><div><strong>{{ item.health.account || (item.provider==='apple'?'Local Mac apps':'Google direct cloud') }}</strong><small>{{ item.config.enabled?'Scheduled':'Manual only' }} · {{ item.health.state?.replaceAll('_',' ') }}</small><small v-if="item.health.error">{{ item.health.error }}</small></div><button class="usx-btn" :disabled="busy" @click="run(item.id)"><UIcon name="sync" />Sync now</button></article><p v-if="message" role="status">{{ message }}</p></section></template>
<script setup lang="ts">
import { onMounted,ref } from 'vue';import { useRouter } from 'vue-router';import { UCORE_BASE } from '../../api/base';import UIcon from '../atoms/UIcon.vue';
const router=useRouter(),connections=ref<any[]>([]),busy=ref(false),error=ref(''),message=ref('');
async function api(body?:object){const response=await fetch(`${UCORE_BASE}/api/snackbar/sync`,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});if(!response.ok)throw Error((await response.text()).slice(0,200));return response.json();}
async function load(){busy.value=true;try{connections.value=(await api()).connections;error.value='';}catch(e){error.value=e instanceof Error?e.message:'Sync status unavailable';}finally{busy.value=false;}}
async function run(connection:string){busy.value=true;error.value='';try{const result=await api({connection});message.value=result.error||`Sync: ${result.state}`;connections.value=(await api()).connections;}catch(e){error.value=e instanceof Error?e.message:'Sync unavailable';}finally{busy.value=false;}}
onMounted(load);
</script>
<style scoped>.sync-panel{text-align:left;padding:16px;border:1px solid var(--usx-color-border);border-radius:var(--usx-radius-sm);}.sync-panel header{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.sync-panel header>div{flex:1;min-width:12rem}.sync-panel h3,.sync-panel p{margin:0 0 8px}.sync-panel p,small{font-size:var(--usx-font-size-sm);color:var(--usx-color-on-surface-muted)}article{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:8px 0;border-top:1px solid var(--usx-color-border)}article div{display:grid;gap:4px}.usx-btn{display:inline-flex;align-items:center;gap:6px;margin:0;min-height:32px;padding:4px 8px}.sync-panel [role=alert]{color:var(--usx-color-danger)}</style>
